// Package avatars embeds the bundled profile avatar catalog (CC0 artwork only,
// generated by generate/generate.mjs) and serves it.
package avatars

import (
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"path"
	"strings"
	"sync"
)

//go:embed catalog.json files/*.svg
var embedded embed.FS

// URLPrefix is where the avatar images are served (outside /api, no server password,
// so <img> tags work on every client).
const URLPrefix = "/profile-avatars/"

// Avatar is one entry of catalog.json.
type Avatar struct {
	ID         string `json:"id"`
	File       string `json:"file"`
	Category   string `json:"category"`
	Label      string `json:"label"`
	License    string `json:"license"`
	LicenseURL string `json:"licenseUrl"`
	Creator    string `json:"creator"`
	Source     string `json:"source"`
	Origin     string `json:"origin"`
	URL        string `json:"url"` // Filled at load time: URLPrefix + File
}

var (
	loadOnce sync.Once
	catalog  []*Avatar
	byID     map[string]*Avatar
	loadErr  error
)

func load() {
	data, err := embedded.ReadFile("catalog.json")
	if err != nil {
		loadErr = err
		return
	}
	if err := json.Unmarshal(data, &catalog); err != nil {
		loadErr = fmt.Errorf("avatars: parse catalog.json: %w", err)
		return
	}
	byID = make(map[string]*Avatar, len(catalog))
	for _, a := range catalog {
		a.URL = URLPrefix + a.File
		byID[a.ID] = a
	}
	loadErr = validate(catalog, embedded)
}

// validate checks that every entry has an id, licence, source and an existing file.
func validate(list []*Avatar, fsys fs.FS) error {
	if len(list) == 0 {
		return errors.New("avatars: catalog is empty")
	}
	seen := map[string]bool{}
	var errs []error
	for i, a := range list {
		switch {
		case a.ID == "":
			errs = append(errs, fmt.Errorf("entry %d: missing id", i))
			continue
		case seen[a.ID]:
			errs = append(errs, fmt.Errorf("%s: duplicate id", a.ID))
		}
		seen[a.ID] = true
		if strings.TrimSpace(a.License) == "" {
			errs = append(errs, fmt.Errorf("%s: missing license", a.ID))
		}
		if strings.TrimSpace(a.Source) == "" {
			errs = append(errs, fmt.Errorf("%s: missing source", a.ID))
		}
		if a.File == "" || path.Base(a.File) != a.File {
			errs = append(errs, fmt.Errorf("%s: invalid file %q", a.ID, a.File))
			continue
		}
		if _, err := fs.Stat(fsys, "files/"+a.File); err != nil {
			errs = append(errs, fmt.Errorf("%s: file %s not found", a.ID, a.File))
		}
	}
	return errors.Join(errs...)
}

// Validate returns an error if the embedded catalog is inconsistent.
func Validate() error {
	loadOnce.Do(load)
	return loadErr
}

// Catalog returns the avatar list in catalog order.
func Catalog() []*Avatar {
	loadOnce.Do(load)
	return catalog
}

// Get returns the avatar with the given id.
func Get(id string) (*Avatar, bool) {
	loadOnce.Do(load)
	a, ok := byID[id]
	return a, ok
}

// Exists reports whether the id is in the catalog.
func Exists(id string) bool {
	_, ok := Get(id)
	return ok
}

// Fallback returns the avatar used when a stored id no longer exists.
func Fallback() *Avatar {
	c := Catalog()
	if len(c) == 0 {
		return nil
	}
	return c[0]
}

// Resolve returns the avatar for id, or the fallback if the id is unknown.
func Resolve(id string) *Avatar {
	if a, ok := Get(id); ok {
		return a
	}
	return Fallback()
}

// ReadFile returns the bytes and content type of a catalog file (e.g. "gl-lorelei-01.svg").
func ReadFile(file string) ([]byte, string, error) {
	if file == "" || path.Base(file) != file {
		return nil, "", fs.ErrNotExist
	}
	data, err := embedded.ReadFile("files/" + file)
	if err != nil {
		return nil, "", err
	}
	ct := "application/octet-stream"
	switch path.Ext(file) {
	case ".svg":
		ct = "image/svg+xml"
	case ".webp":
		ct = "image/webp"
	case ".png":
		ct = "image/png"
	}
	return data, ct, nil
}
